import type { CEFRLevel, Skill } from '@/lib/types';

/**
 * The content library.
 *
 * The app promises a full year of study: 365 lessons for EVERY skill, so
 * there is always something new. Writing 2,190 lessons by hand would be
 * 2,190 files nobody could maintain, so the library works the other way
 * round: a deep bank of real teaching material per skill, and a composer
 * that turns (learner, day of the year, skill) into a unique lesson.
 *
 * The result is deterministic: the same learner gets the same lesson on the
 * same day of the year, and a different one tomorrow.
 */

export interface GrammarPoint {
  title: string;
  rule: string;
  examples: string[];
  mistake: string;
  fix: string;
  level: CEFRLevel;
  /** A short practice prompt the learner can answer in one line. */
  drill: string;
  answer: string;
}

export const GRAMMAR_POINTS: GrammarPoint[] = [
  { title: 'Present simple: habits and facts', rule: 'Use the present simple for things that are true in general: habits, routines, facts and timetables.', examples: ['I drink coffee every morning.', 'The train leaves at 6:40.', 'Water boils at 100 degrees.'], mistake: 'She drink tea every day.', fix: 'She drinks tea every day.', level: 'A1', drill: 'Complete: "They ___ (play) football on Saturdays."', answer: 'play' },
  { title: 'Present simple with "be"', rule: 'With the verb "be" the present simple is just "am / is / are" — never "be" on its own.', examples: ['I am tired.', 'She is at home.', 'They are ready.'], mistake: 'He be my brother.', fix: 'He is my brother.', level: 'A1', drill: 'Complete: "My parents ___ (be) from Egypt."', answer: 'are' },
  { title: 'Third person -s', rule: 'He, she and it take -s in the present simple: work → works, but "have" is always "has".', examples: ['He watches TV at night.', 'She has two sisters.', 'It rains in April.'], mistake: 'My brother play football.', fix: 'My brother plays football.', level: 'A1', drill: 'Complete: "The sun ___ (rise) in the east."', answer: 'rises' },
  { title: 'Present continuous', rule: 'Use am/is/are + verb-ing for what is happening right now, and for arrangements in the near future.', examples: ['I am studying right now.', 'We are meeting them tomorrow.'], mistake: 'She is work at the moment.', fix: 'She is working at the moment.', level: 'A2', drill: 'Complete: "Look! It ___ (rain) again."', answer: 'is raining' },
  { title: 'Past simple: regular verbs', rule: 'Regular verbs take -ed. Pronunciation changes: work → worked, but stop → stopped and plan → planned.', examples: ['I worked late yesterday.', 'We visited my grandmother.', 'They planned the trip.'], mistake: 'I goed to the market.', fix: 'I went to the market.', level: 'A2', drill: 'Complete: "We ___ (watch) a film yesterday."', answer: 'watched' },
  { title: 'Past simple: irregular verbs', rule: 'Many common verbs do not take -ed: go → went, see → saw, buy → bought, take → took.', examples: ['She went to school.', 'I saw him yesterday.', 'He bought a new phone.'], mistake: 'I buyed a ticket.', fix: 'I bought a ticket.', level: 'A2', drill: 'Complete: "They ___ (take) the early train."', answer: 'took' },
  { title: 'Past simple with negatives and questions', rule: 'The form is the same in all three forms: "did not" / "did you" + the BASE verb.', examples: ['I did not go out.', 'Did you finish it?', 'She did not call.'], mistake: 'Did you went there?', fix: 'Did you go there?', level: 'A2', drill: 'Complete: "He ___ (not / like) the food."', answer: 'did not like' },
  { title: 'Present perfect: ever and never', rule: 'Present perfect talks about the past without saying when. Use it with "ever" and "never".', examples: ['I have never been to Japan.', 'Have you ever eaten sushi?'], mistake: 'Did you ever visit Paris?', fix: 'Have you ever visited Paris?', level: 'A2', drill: 'Complete: "She ___ (never / be) late."', answer: 'has never been' },
  { title: 'Present perfect vs past simple', rule: 'Use the past simple with a finished time (yesterday, in 2019). Use the present perfect when the time is not stated, or when it still matters now.', examples: ['I saw him yesterday.', 'I have seen that film before.'], mistake: 'I have seen him yesterday.', fix: 'I saw him yesterday.', level: 'B1', drill: 'Choose: "I ___ (finish) my homework an hour ago."', answer: 'finished' },
  { title: 'for, since, in, during', rule: '"for" takes a duration, "since" takes a starting point, "in" takes a year or a month, "during" takes a period.', examples: ['for three years', 'since 2020', 'in July', 'during the war'], mistake: 'I worked here since two years.', fix: 'I have worked here for two years.', level: 'B1', drill: 'Choose: "She has lived here ___ 2019."', answer: 'since' },
  { title: 'Comparative adjectives', rule: 'Short adjectives add -er (taller), long adjectives use "more" (more expensive). Irregulars: good → better, bad → worse, far → further.', examples: ['This road is wider.', 'It is more expensive.', 'She is better at maths than I am.'], mistake: 'This is more taller.', fix: 'This is taller.', level: 'A2', drill: 'Complete: "Today is ___ (hot) than yesterday."', answer: 'hotter' },
  { title: 'Superlative adjectives', rule: 'The superlative uses "the" + adjective + -est, or "the most" + adjective.', examples: ['the tallest building', 'the most expensive car', 'the best day of my life'], mistake: 'It is the most tallest.', fix: 'It is the tallest.', level: 'A2', drill: 'Complete: "She is ___ (good) singer in the class."', answer: 'the best' },
  { title: 'Article: a / an', rule: '"a" before a consonant sound, "an" before a vowel SOUND. That is why it is "an hour" and "a university".', examples: ['a book', 'an apple', 'an hour', 'a university'], mistake: 'I saw a elephant.', fix: 'I saw an elephant.', level: 'A1', drill: 'Choose: "It will take ___ hour."', answer: 'an' },
  { title: 'Article: the', rule: '"The" is used when both speakers know which one: the book I mentioned, the sun, the internet, the first time.', examples: ['the book on the table', 'the sun', 'the same', 'the last one'], mistake: 'I like the music.', fix: 'I like music.', level: 'B1', drill: 'Choose: "___ life is short."', answer: 'Life' },
  { title: 'Countable and uncountable nouns', rule: 'Uncountable nouns (advice, information, furniture) have no plural and take "much", not "many".', examples: ['a piece of advice', 'much information', 'some furniture'], mistake: 'I have many advices.', fix: 'I have a lot of advice.', level: 'B1', drill: 'Choose: "She gave me some ___ (information)."', answer: 'information' },
  { title: 'There is / there are', rule: '"There is" introduces existence: there is a problem, there are two reasons.', examples: ['There is no answer.', 'There are many reasons to try.'], mistake: 'There have a problem.', fix: 'There is a problem.', level: 'A1', drill: 'Complete: "___ are three books on the desk."', answer: 'There' },
  { title: 'have got / have', rule: 'In British English "have got" is common for possession; in American English "have" is used.', examples: ['I have got a car.', 'I have a sister.'], mistake: 'She have got two kids.', fix: 'She has got two kids.', level: 'A2', drill: 'Complete: "He ___ got a new phone."', answer: 'has' },
  { title: 'Modal verbs: can, could, may', rule: '"Can" is ability, "could" is past ability or a polite request, "may" is formal permission.', examples: ['I can swim.', 'Could you help me?', 'May I speak, please?'], mistake: 'I can to swim.', fix: 'I can swim.', level: 'A2', drill: 'Complete: "___ you open the window?"', answer: 'Could' },
  { title: 'Modal verbs: must, have to, should', rule: '"Must" is from the speaker, "have to" is from outside, "should" is advice.', examples: ['You must be here at eight.', 'I have to work late.', 'You should try again.'], mistake: 'I must to go now.', fix: 'I must go now.', level: 'B1', drill: 'Complete: "You ___ wear a seatbelt."', answer: 'must' },
  { title: 'First and second conditionals', rule: 'First: if + present, will + verb (real). Second: if + past, would + verb (unreal).', examples: ['If it rains, I will stay home.', 'If I had money, I would travel.'], mistake: 'If I would have time, I would help.', fix: 'If I had time, I would help.', level: 'B1', drill: 'Complete: "If I ___ (be) taller, I would play basketball."', answer: 'were' },
  { title: 'Third conditional', rule: 'For a past that did not happen: if + had + past participle, would have + past participle.', examples: ['If I had studied, I would have passed.', 'She would have helped if you had asked.'], mistake: 'If I would have known, I would come.', fix: 'If I had known, I would have come.', level: 'B2', drill: 'Complete: "If he ___ (study) more, he would have passed."', answer: 'had studied' },
  { title: 'Mixed conditionals', rule: 'A past condition can produce a present result: if I had taken that job, I would be living in Berlin now.', examples: ['If she had left earlier, she would be here now.', 'If I had taken the job, I would be living in Berlin now.'], mistake: 'If I had bought the house, I would live there now.', fix: 'If I had bought the house, I would be living there now.', level: 'B2', drill: 'Complete: "If we had left earlier, we ___ (be) on the train now."', answer: 'would be' },
  { title: 'Relative clauses: who, which, that', rule: 'Use "who" for people, "which" for things, "that" for both. A defining clause has no comma.', examples: ['The woman who called you is my sister.', 'The book which I read was good.'], mistake: 'My car, that is red, is old.', fix: 'My car, which is red, is old.', level: 'B1', drill: 'Complete: "The film ___ I watched last night was great."', answer: 'which' },
  { title: 'Defining vs non-defining clauses', rule: 'A defining clause tells us WHICH one (no comma). A non-defining clause adds extra information (with a comma).', examples: ['My brother, who lives in Paris, is a doctor.', 'The house that I grew up in is small.'], mistake: 'The students, who study in the morning, passed.', fix: 'The students who study in the morning passed.', level: 'B2', drill: 'Add a comma: "My sister, ___ lives in Rome, is a teacher."', answer: 'who' },
  { title: 'The passive voice', rule: 'Passive = be + past participle. Use it when the action matters more than the doer.', examples: ['The bridge was built in 1890.', 'English is spoken here.', 'The report has been sent.'], mistake: 'The bridge was build in 1890.', fix: 'The bridge was built in 1890.', level: 'B1', drill: 'Complete: "The window ___ (break) yesterday."', answer: 'was broken' },
  { title: 'Reported speech: statements', rule: 'When reporting: back → back, here → there, today → that day, and the verb goes one step back in the past.', examples: ['"I am busy", she said. → She said she was busy.', 'He said, "I will call you." → He said he would call you.'], mistake: 'She said "I am busy".', fix: 'She said she was busy.', level: 'B1', drill: 'Report: "I live in Paris." → "He said he ___ in Paris."', answer: 'lived' },
  { title: 'Reported speech: questions and commands', rule: 'Questions become "if/whether" with the word order of a statement. Commands use "told me to".', examples: ['"Where do you live?" → She asked where I lived.', '"Call me." → He told me to call him.'], mistake: 'She asked where did I live.', fix: 'She asked where I lived.', level: 'B2', drill: 'Report: "Are you ready?" → "She asked if I ___ ready."', answer: 'was' },
  { title: 'Question forms', rule: 'Most questions invert the subject and the auxiliary: "Do you like…?", "Is she coming?", "Have they finished?"', examples: ['Do you know the answer?', 'Is it raining?', 'Have you seen it?'], mistake: 'You do like it?', fix: 'Do you like it?', level: 'A1', drill: 'Complete: "___ you speak French?"', answer: 'Do' },
  { title: 'Subject questions', rule: 'When the question asks for the SUBJECT, the word order does not change: "Who called you?" "What happened?"', examples: ['Who broke the window?', 'What caused the delay?'], mistake: 'Who did call you?', fix: 'Who called you?', level: 'B2', drill: 'Complete: "___ wrote this poem?"', answer: 'Who' },
  { title: 'Tag questions', rule: 'A short tag repeats the meaning: "You are tired, aren\'t you?" Positive → negative tag, negative → positive.', examples: ['It\'s cold, isn\'t it?', 'You don\'t agree, do you?'], mistake: 'It\'s cold, is it?', fix: 'It\'s cold, isn\'t it?', level: 'B1', drill: 'Add the tag: "You are ready, ___?"', answer: 'aren\'t you' },
  { title: 'Prepositions of time: in, on, at', rule: '"at" for a point (at six), "on" for a day or date (on Monday, on 5 May), "in" for a longer period (in June, in 2024).', examples: ['at 7:30', 'on Friday', 'in the morning', 'in 1998'], mistake: 'See you in Monday.', fix: 'See you on Monday.', level: 'A1', drill: 'Choose: "The exam is ___ 9 am."', answer: 'at' },
  { title: 'Prepositions of place', rule: '"at" for a point, "in" for an enclosed space, "on" for a surface.', examples: ['at the bus stop', 'in the kitchen', 'on the table', 'on the bus'], mistake: 'The keys are in the table.', fix: 'The keys are on the table.', level: 'A1', drill: 'Choose: "She is waiting ___ the station."', answer: 'at' },
  { title: 'Collocations: make, do, take', rule: 'MAKE = create (make a decision, make a mistake), DO = tasks (do homework, do a job), TAKE = accept or carry (take a photo, take medicine).', examples: ['make a decision', 'do the dishes', 'take a break'], mistake: 'I did a mistake.', fix: 'I made a mistake.', level: 'B1', drill: 'Complete: "Let me ___ a photo of this."', answer: 'take' },
  { title: 'Word + preposition', rule: 'Some verbs are followed by a fixed preposition: depend ON, consist OF, agree WITH, apologise FOR.', examples: ['It depends on the weather.', 'The team consists of six people.'], mistake: 'It depends of the weather.', fix: 'It depends on the weather.', level: 'B1', drill: 'Complete: "I apologise ___ the delay."', answer: 'for' },
  { title: 'Adverbs of frequency', rule: 'Frequency adverbs go BEFORE the main verb but AFTER the verb "be": "I always eat", "He is always late".', examples: ['She never complains.', 'They are often late.', 'I rarely eat meat.'], mistake: 'I eat always breakfast.', fix: 'I always eat breakfast.', level: 'A2', drill: 'Place it: "He is ___ (never) rude."', answer: 'never' },
  { title: 'Adverbs: manner and degree', rule: 'Manner answers "how?" (quickly, carefully), degree answers "how much?" (very, quite, rather).', examples: ['She spoke softly.', 'It is rather cold.', 'He drives very carefully.'], mistake: 'He runs very fastly.', fix: 'He runs very fast.', level: 'A2', drill: 'Choose: "The test was ___ (quite/easily) difficult."', answer: 'quite' },
  { title: 'Linking words: adding', rule: 'Use and, but, so, because, therefore, however to join ideas. A full stop + a linker is safer than a comma splice.', examples: ['It was raining, so we stayed in.', 'However, the results were good.'], mistake: 'It was raining, so we stayed in.', fix: 'It was raining, so we stayed in.', level: 'B1', drill: 'Complete: "She studied hard; ___, she passed."', answer: 'therefore' },
  { title: 'Linking words: contrast', rule: 'Contrast words: although, though, even though, whereas, despite, in spite of.', examples: ['Although it was late, she continued.', 'Despite the rain, we walked.'], mistake: 'Despite of the rain, we walked.', fix: 'Despite the rain, we walked.', level: 'B1', drill: 'Complete: "___ he was tired, he finished."', answer: 'Although' },
  { title: "The gerund and the infinitive", rule: 'After enjoy, avoid, finish, suggest, mind: + -ing. After decide, hope, plan, want, agree: + to + verb.', examples: ['I enjoy reading.', 'I decided to leave.', 'She suggested waiting.'], mistake: 'I enjoy to read.', fix: 'I enjoy reading.', level: 'B1', drill: 'Complete: "Would you mind ___ (opening) the window?"', answer: 'opening' },
  { title: 'The infinitive with purpose', rule: 'Use "to + verb" to explain why: "I called to cancel my booking."', examples: ['I went early to get a seat.', 'She called to thank him.'], mistake: 'I went early for get a seat.', fix: 'I went early to get a seat.', level: 'B1', drill: 'Complete: "He left early ___ (catch) the train."', answer: 'to catch' },
  { title: 'Too vs enough', rule: '"Too" = more than you want; "enough" = as much as you need. The word order changes with the adjective.', examples: ['This is too expensive.', 'This is expensive enough.', 'It is not good enough.'], mistake: 'It is enough cheap.', fix: 'It is cheap enough.', level: 'B1', drill: 'Choose: "The room is ___ (too/enough) noisy for me."', answer: 'too' },
  { title: 'So and such', rule: '"So" + adjective + a. "Such" + (a/an) + adjective + noun.', examples: ['It was so cold that we stayed in.', 'It was such a cold day.'], mistake: 'It was such cold day.', fix: 'It was such a cold day.', level: 'B2', drill: 'Complete: "It was ___ a beautiful morning."', answer: 'such' },
  { title: 'Word order in questions with adverbs', rule: 'The adverb sits before the main verb: "Do you often work late?" not "Do you work often late?"', examples: ['Did you often travel alone?', 'Can you really finish it today?'], mistake: 'Do you work often late?', fix: 'Do you often work late?', level: 'B1', drill: 'Place it: "Can you ___ (really) come?"', answer: 'really' },
  { title: 'Hedging and softening', rule: 'Professional English softens claims: "It would seem that…", "One might argue that…", "It is fairly clear that…".', examples: ['It would appear that the trend continues.', 'One might argue the opposite.'], mistake: 'It is clear that everything is bad.', fix: 'It is fairly clear that the results are mixed.', level: 'C1', drill: 'Rewrite with a hedge: "This proves he lied."', answer: 'This would appear to prove he lied.' },
  { title: 'Nominalisation', rule: 'Formal writing prefers nouns to verbs: "the implementation of" rather than "we implemented".', examples: ['the implementation of the policy', 'a decision was taken'], mistake: 'We implemented the policy.', fix: 'The implementation of the policy was delayed.', level: 'C1', drill: 'Formalise: "We rejected the offer." → "The offer was ___."', answer: 'rejected' },
  { title: 'Concord and number agreement', rule: 'The verb agrees with the subject, not the nearest noun: "The list of items IS ready."', examples: ['The quality of the photos is excellent.', 'Each student has a book.'], mistake: 'The list of items are ready.', fix: 'The list of items is ready.', level: 'B2', drill: 'Fix: "The team of players are winning."', answer: 'is' },
  { title: 'Articles in formal writing', rule: 'In academic prose, abstract nouns usually take no article: "in the absence of evidence", "regardless of age".', examples: ['in the absence of data', 'regardless of age'], mistake: 'In the absence of the data.', fix: 'In the absence of data.', level: 'C1', drill: 'Complete: "regardless ___ the weather."', answer: 'of' },
  { title: 'Uncountable quantifiers', rule: '"A piece of" turns an uncountable noun countable: a piece of advice, a piece of evidence.', examples: ['a piece of evidence', 'an item of clothing'], mistake: 'an advice', fix: 'a piece of advice', level: 'B2', drill: 'Complete: "She gave me a useful ___ of advice."', answer: 'piece' },
  { title: 'Phrasal verbs: separable or not', rule: 'Some phrasal verbs are separable (turn the lights OFF), others are not (look AFTER someone).', examples: ['Turn off the lights.', 'Look after your brother.'], mistake: 'Look after your brother is easy.', fix: 'Looking after your brother is easy.', level: 'B2', drill: 'Place it: "Please switch ___ the light."', answer: 'off' },
  { title: 'Phrasal verbs in meaning', rule: 'Many phrasal verbs change meaning completely: "look up" (search) vs "look after" (care for).', examples: ['look up a word', 'look up to someone'], mistake: 'I looked the word up in the dictionary.', fix: 'I looked the word up in the dictionary.', level: 'B2', drill: 'Choose: "I need to ___ (look up / look after) this word."', answer: 'look up' },
  { title: 'Formal email language', rule: 'Open with the purpose, keep it short, and close with a clear next step. Avoid "Dear Sir/Madam" when you know the name.', examples: ['I am writing to confirm our meeting on Tuesday.', 'Please let me know if that works for you.'], mistake: 'Dear sir, I hope this email finds you well and I am writing to ask about…', fix: 'Dear Ms Khan, I am writing to confirm our meeting on Tuesday.', level: 'B1', drill: 'Write the opening for: asking to move a meeting to Thursday.', answer: 'I am writing to ask whether we could move our meeting to Thursday.' },
  { title: 'Polite requests', rule: 'Use "could/would you mind + -ing", "I was wondering if you could…", "Would it be possible to…".', examples: ['Could you mind closing the door?', 'I was wondering if you could send the file.'], mistake: 'Send me the file now.', fix: 'Could you send me the file when you have a moment?', level: 'B1', drill: 'Rewrite politely: "Give me the report."', answer: 'Could you send me the report, please?' },
  { title: 'Describing people and places', rule: 'Adjective + noun + preposition: "a city full of history", "a man known for his honesty".', examples: ['a street lined with trees', 'a decision full of risk'], mistake: 'He is a man known his honesty.', fix: 'He is a man known for his honesty.', level: 'B2', drill: 'Complete: "a city ___ (full/of) narrow streets."', answer: 'full of' },
  { title: 'Making comparisons with as', rule: '"as + adjective + as" for equality; "not as … as" for a difference; "the same as" for identical things.', examples: ['She is as tall as her sister.', 'This is not as good as that one.'], mistake: 'She is so tall as her sister.', fix: 'She is as tall as her sister.', level: 'A2', drill: 'Complete: "He is not ___ (as/as) fast as me."', answer: 'as' },
  { title: 'Future forms', rule: '"will" for decisions and predictions, "be going to" for plans based on present evidence, "present continuous" for arrangements.', examples: ['I will call you later.', 'She is going to travel.', 'I am meeting the dentist at four.'], mistake: 'Look at the sky! It is going to rain.', fix: 'Look at the sky! It is going to rain.', level: 'A2', drill: 'Complete: "I have already bought the ticket, so I ___ going to travel."', answer: 'am' },
  { title: 'Used to and would', rule: '"Used to" describes a habit in the past that is over. "Would" describes a repeated past action.', examples: ['I used to live by the sea.', 'I would visit my grandmother every Sunday.'], mistake: 'I used to be play football.', fix: 'I used to play football.', level: 'B1', drill: 'Complete: "She ___ (use / not) to work at night."', answer: 'used not to' },
  { title: 'Quantity words', rule: '"A few" (positive, countable), "a little" (positive, uncountable), "few" (negative), "little" (negative).', examples: ['a few friends', 'a little sugar', 'few people came', 'little interest'], mistake: 'There are a little apples.', fix: 'There are a few apples.', level: 'B1', drill: 'Choose: "There is ___ water left."', answer: 'a little' },
  { title: 'Counting uncountable nouns', rule: 'Uncountable nouns need a container: "a piece of furniture", "a glass of water", "a kilo of rice".', examples: ['two kilos of rice', 'a piece of furniture'], mistake: 'I bought three furnitures.', fix: 'I bought three pieces of furniture.', level: 'B1', drill: 'Complete: "Could I have a ___ of water?"', answer: 'glass' },
  { title: 'Giving opinions with I think', rule: 'In speech the tag comes first: "I think it is fine", "I don\'t think it matters". In writing, avoid over-using it.', examples: ['I think we should wait.', 'I don\'t think that is right.'], mistake: 'It is fine I think.', fix: 'I think it is fine.', level: 'A2', drill: 'Place it: "___ think it is fine."', answer: 'I' },
  { title: 'Conversation: interrupting politely', rule: '"Sorry to interrupt, but…" or "Can I just add something here?" is polite; starting a new sentence is not.', examples: ['Sorry to interrupt, but could I add one thing?', 'Can I just come in here?'], mistake: 'Wait. I want to say something else.', fix: 'Sorry to interrupt — may I add one thing?', level: 'B2', drill: 'Make it polite: "Stop. I have a question."', answer: 'Sorry to interrupt — may I ask you something?' },
  { title: 'Conversation: disagreeing at work', rule: 'Acknowledge, then differ, then propose: "I see your point, however… Could we…?"', examples: ['I see your point, however the deadline is fixed. Could we discuss the scope instead?', 'The plan works, although the budget is tight.'], mistake: 'No, that is wrong.', fix: 'I see your point, however I think there is a risk here.', level: 'B2', drill: 'Rewrite politely: "That plan is bad."', answer: 'I see why you think that, however I am not sure it will work.' },
  { title: 'Register: formal vs informal', rule: 'Formal writing avoids contractions, slang and first-person opinions; it uses complete clauses and precise verbs.', examples: ['We would be grateful for your response.', 'I am writing to ask about…'], mistake: 'Hey, can u send me that file asap?', fix: 'Could you send me that file at your earliest convenience?', level: 'B1', drill: 'Make it formal: "Hey, thanks for the info."', answer: 'Thank you for the information.' },
  { title: 'Hedges and intensifiers', rule: 'Hedges lower the certainty: may, might, could, tend to. Intensifiers raise it: definitely, certainly, absolutely.', examples: ['The results may suggest a link.', 'That is absolutely correct.'], mistake: 'Maybe possibly we could consider it.', fix: 'We could possibly consider it.', level: 'C1', drill: 'Rewrite with a hedge: "He definitely left."', answer: 'He may well have left.' },
  { title: 'Modals of deduction', rule: 'Must = almost certain, might = possible, can\'t = almost impossible — in the present. Past: must have, might have, can\'t have.', examples: ['She must be tired.', 'He can\'t have known.', 'They might have left already.'], mistake: 'He must left early.', fix: 'He must have left early.', level: 'B2', drill: 'Complete: "The lights are on — they ___ (must) be home."', answer: 'must' },
  { title: 'Time clauses', rule: 'When, as soon as, after, before, until, once + present simple for the future; + past simple for the past.', examples: ['I will call you when I arrive.', 'I called after I had left.'], mistake: 'I will call you when I will arrive.', fix: 'I will call you when I arrive.', level: 'B1', drill: 'Complete: "Call me as soon as you ___ (arrive)."', answer: 'arrive' },
  { title: 'Sequence: first, then, after that, finally', rule: 'Words of sequence organise a story or a process clearly.', examples: ['First, mix the eggs. Then, add the flour.', 'Finally, check the results.'], mistake: 'Firstly mix the eggs, after that bake it, and in the end it is ready.', fix: 'First mix the eggs. Then bake it. Finally, let it cool.', level: 'B1', drill: 'Order: "Add the flour, ___ bake the cake."', answer: 'then' },
  { title: 'Purpose: so that, in order to', rule: '"So that" introduces a clause with a subject; "in order to" introduces a verb phrase.', examples: ['I arrived early so that I could find a seat.', 'I arrived early in order to find a seat.'], mistake: 'I left early for catch the last train.', fix: 'I left early to catch the last train.', level: 'B1', drill: 'Complete: "She spoke up so that everyone ___ (hear) her."', answer: 'could hear' },
  { title: 'Concession', rule: '"Although/while/whereas + clause" concedes a point before the main argument.', examples: ['Although the data was limited, the trend was clear.', 'Whereas some prefer audio, others prefer video.'], mistake: 'Although the rain, we went out.', fix: 'Although it was raining, we went out.', level: 'B2', drill: 'Complete: "___ the cost, the project continued."', answer: 'Despite the cost' },
  { title: 'Cause and effect: because, due to, owing to', rule: '"Because" starts a clause; "due to" and "owing to" come after a noun or before a noun phrase.', examples: ['The match was cancelled because of the storm.', 'Due to the storm, the match was cancelled.'], mistake: 'Due to the match was cancelled.', fix: 'The match was cancelled due to the storm.', level: 'B2', drill: 'Choose: "The delay was caused ___ heavy rain."', answer: 'by' },
  { title: 'Idioms: work', rule: 'Common idioms with "work": work out (resolve), work on (improve), work off (burn energy).', examples: ['It will work out in the end.', 'I am working on my pronunciation.'], mistake: 'Everything will work on.', fix: 'Everything will work out.', level: 'B2', drill: 'Complete: "Let\'s work ___ the details tomorrow."', answer: 'out' },
  { title: 'Phrasal verbs: give and take', rule: 'Give up (stop), give in (yield), give away (reveal), take over (assume control).', examples: ['He gave up smoking.', 'She gave in to pressure.'], mistake: 'He gave away of the secret.', fix: 'He gave away the secret.', level: 'B2', drill: 'Complete: "Don\'t ___ up — you are close."', answer: 'give' },
  { title: 'Word families and collocations', rule: 'Learn words with their natural partners: make a decision, strong opinion, heavy rain, raise a question.', examples: ['She raised a question.', 'There was heavy rain.'], mistake: 'She did a question.', fix: 'She raised a question.', level: 'B2', drill: 'Choose: "make / do / raise a suggestion."', answer: 'raise' },
  { title: 'Precision in numbers', rule: 'Choose the exact word: approximate, roughly, about, nearly, over, under, up to.', examples: ['Approximately 200 people.', 'Nearly half of them agreed.'], mistake: 'About exactly 200 people came.', fix: 'Approximately 200 people came.', level: 'C1', drill: 'Choose: "___ 30% of the group declined."', answer: 'Nearly' },
  { title: 'Degrees of certainty in reports', rule: '"Study finds", "research suggests", "data indicate" — the verb carries the level of confidence.', examples: ['The study finds a clear link.', 'Initial data suggest a trend.'], mistake: 'The study proves it.', fix: 'The study finds a clear link.', level: 'C1', drill: 'Complete: "Early data ___ (suggest/indicate/prove) a modest improvement."', answer: 'suggest' },
  { title: 'Argument structure', rule: 'A strong paragraph = claim, evidence, reasoning, and a link back to the question.', examples: ['Cost is the main barrier. A third of respondents cited it. This suggests… therefore…', 'The sample was small. Therefore, the result must be treated with care.'], mistake: 'Cost is a problem. Many people agree. It is expensive.', fix: 'Add evidence and a link back to the question.', level: 'C1', drill: 'What is missing from "X is bad. Y agrees."?', answer: 'Evidence and reasoning' },
  { title: 'Describing change over time', rule: 'For trends: rose, fell, remained stable, peaked, doubled, plateaued.', examples: ['Figures rose steadily until 2019, then plateaued.', 'The gap widened considerably.'], mistake: 'The number went up and down a lot over the time.', fix: 'The number fluctuated considerably over the period.', level: 'C1', drill: 'Choose: "Prices ___ steadily over the decade."', answer: 'rose' },
  { title: 'Reporting findings cautiously', rule: 'Use hedging verbs and adverbs: "may be associated with", "appears to correlate", "suggests a possible link".', examples: ['The data suggest a possible link.', 'Higher income appears to correlate with faster recovery.'], mistake: 'Income causes faster recovery.', fix: 'Higher income appears to correlate with faster recovery.', level: 'C1', drill: 'Rewrite carefully: "Smoking causes cancer."', answer: 'Smoking is strongly associated with an increased risk of cancer.' },
  { title: 'Nuance: although, whereas, despite', rule: 'Nuance is the difference between "different" and "not the same". Small words carry it.', examples: ['The plan is cheaper, although less flexible.', 'She was tired, although she kept working.'], mistake: 'The plan is different.', fix: 'The plan is cheaper, although less flexible.', level: 'C2', drill: 'Complete: "The two versions are similar, ___ not identical."', answer: 'although' },
  { title: 'Condensed formal register', rule: 'Formal writing compresses: "notwithstanding" for "despite", "in the event that" for "if", "prior to" for "before".', examples: ['Prior to the meeting, the papers were circulated.', 'In the event that it rains, we will move indoors.'], mistake: 'Before the meeting happened, the papers were circulated.', fix: 'Prior to the meeting, the papers were circulated.', level: 'C2', drill: 'Formalise: "before the deadline" → "___ the deadline"', answer: 'Prior to' },
  { title: 'Lexical nuance: say, state, claim', rule: '"Say" is neutral, "state" is formal and factual, "claim" signals doubt about the truth.', examples: ['He stated that the figures were provisional.', 'They claim the method is novel.'], mistake: 'He said that the figures were provisional.', fix: 'He stated that the figures were provisional.', level: 'C2', drill: 'Choose the sceptical word: "They ___ the results are conclusive."', answer: 'claim' },
  { title: 'Cleft sentences for emphasis', rule: 'Clefts highlight one element: "It was Sara who called.", "What I need is time."', examples: ['What matters is the preparation.', 'It was not the money that stopped him.'], mistake: 'The preparation is the important thing for me.', fix: 'What matters is the preparation.', level: 'C2', drill: 'Rewrite for emphasis: "She called me yesterday."', answer: 'It was she who called me yesterday.' },
  { title: 'Participial clauses', rule: 'Present and past participles compress clauses: "Walking home, I saw him."', examples: ['Feeling tired, she stopped early.', 'Given the evidence, the conclusion is clear.'], mistake: 'Because she was tired, she stopped early.', fix: 'Feeling tired, she stopped early.', level: 'C2', drill: 'Compress: "Because it was raining, we stayed in."', answer: 'It being raining, we stayed in.' },
  { title: 'Inversion for emphasis', rule: 'Negative adverbials at the start invert the subject and auxiliary: "Never have I seen…", "Rarely does he…".', examples: ['Never have I seen such a mess.', 'Seldom does she complain.'], mistake: 'Never I have seen such a mess.', fix: 'Never have I seen such a mess.', level: 'C2', drill: 'Invert: "Not once did he arrive late."', answer: 'Not once did he arrive late.' },
  { title: 'Future perfect and future continuous', rule: 'Future perfect: "will have finished" (before a future point). Future continuous: "will be working" (in the future).', examples: ['By June I will have been here a year.', 'This time tomorrow I will be flying to Rome.'], mistake: 'By June I will finish here a year.', fix: 'By June I will have been here a year.', level: 'B2', drill: 'Complete: "By the time you arrive, I ___ (wait) for two hours."', answer: 'will have been waiting' },
  { title: 'The perfect continuous', rule: 'Present perfect continuous: an action that started in the past and is still going, or its recent effect.', examples: ['I have been working here for ten years.', "I've been waiting for an hour."], mistake: 'I am working here since ten years.', fix: 'I have been working here for ten years.', level: 'B2', drill: 'Complete: "She ___ (study) all morning."', answer: 'has been studying' },
  { title: 'Narrative tenses', rule: 'A story moves from past to present: past simple for the events, present simple for the lasting result.', examples: ['He left, and now he lives in Berlin.', 'She went to Paris and now she works there.'], mistake: 'He has left and now he lives in Berlin.', fix: 'He left, and now he lives in Berlin.', level: 'B2', drill: 'Complete: "She went to Paris and now she ___ (live) there."', answer: 'lives' },
  { title: 'Purpose clauses with so that', rule: '"so that" states a purpose with intent: "I wrote it down so that I would not forget."', examples: ['She spoke up so that everyone could hear.', 'I wrote it down so that I would not forget.'], mistake: 'She spoke up for everyone could hear.', fix: 'She spoke up so that everyone could hear.', level: 'B2', drill: 'Complete: "He left early ___ (catch) the last train."', answer: 'so that he could catch' },
  { title: 'Reporting modal verbs', rule: 'Modals rarely change in reported speech: "He said he would help", "She said she could come".', examples: ['He said he would help.', 'She said she might come.'], mistake: 'He said he will help.', fix: 'He said he would help.', level: 'B2', drill: 'Report: "I can do it." → "He said he ___ do it."', answer: 'could' },
  { title: 'Questions with "what if" and "how come"', rule: '"What if" asks about a hypothetical; "how come" asks for a reason (informal).', examples: ['What if we leave an hour earlier?', 'How come you never told me?'], mistake: 'What if you told me?', fix: 'How come you never told me?', level: 'B2', drill: 'Choose: "___ you never said anything?"', answer: 'How come' },
  { title: 'Formal invitations and offers', rule: 'Professional offers use "would you like to…", "I was wondering whether you could…", "would it be possible…".', examples: ['Would it be possible to move the deadline?', 'I was wondering whether you could join us.'], mistake: 'Come to the meeting at 3.', fix: 'Would it be possible to move the meeting to three?', level: 'B2', drill: 'Make it formal: "Come to the meeting at 3."', answer: 'Would it be possible to meet at three?' },
  { title: 'Time expressions: at, on, in, by, until', rule: '"by" = no later than, "until" = up to a point in time, "for" = duration, "since" = start.', examples: ['Finish by Friday.', 'Wait until Monday.', 'It has been three days.'], mistake: 'Finish until Friday.', fix: 'Finish by Friday.', level: 'B1', drill: 'Choose: "The deadline is ___ Friday."', answer: 'by' },
  { title: 'The word "get"', rule: '"Get" has many faces: get + adjective (become), get + object (obtain), get + to (manage to), get + past participle (passive).', examples: ['She got the job.', 'He got promoted.', 'I got picked.'], mistake: 'I got hire.', fix: 'I got hired.', level: 'B2', drill: 'Complete: "After the interview she ___ hired."', answer: 'got' },
  { title: 'Counting: "each", "every", "all"', rule: '"Each" and "every" take a singular noun and verb; "all" takes a plural.', examples: ['Each student has a book.', 'Every student has a book.', 'All the students have books.'], mistake: 'Every students have a book.', fix: 'Every student has a book.', level: 'B1', drill: 'Fix: "All of the information are ready."', answer: 'information is' },
  { title: 'Adjectives ending in -ing and -ed', rule: '-ing describes the action (an interesting book), -ed describes the result (an interested student).', examples: ['The lecture was boring.', 'The students were bored.'], mistake: 'I am boring in this meeting.', fix: 'I am bored in this meeting.', level: 'B1', drill: 'Fix: "The film was very interesting."', answer: 'interesting' },
  { title: 'Verb + adverb or adjective', rule: 'Some verbs take an adverb (agree, argue, complain) and others an adjective (look, seem, feel).', examples: ['He looks happy.', 'They agreed quickly.'], mistake: 'He looks happily today.', fix: 'He looks happy today.', level: 'B2', drill: 'Choose: "She agreed ___ to the plan."', answer: 'readily' },
  { title: 'Reducing clauses: with, without, in spite of', rule: '"With" + noun + participle replaces "while/when" + clause: "He walked, with the rain falling."', examples: ['She left, with everyone watching.', 'He smiled, with the rain falling outside.'], mistake: 'She left, while the rain was falling.', fix: 'She left, with the rain falling.', level: 'C1', drill: 'Reduce: "He smiled while he opened the door."', answer: 'He smiled, opening the door.' },
  { title: 'Formal vs informal register in emails', rule: 'In a formal email, avoid contractions and exclamation marks, and keep sentences short.', examples: ['Please find the report attached.', 'Do not hesitate to contact me.'], mistake: "Here's the report — let me know if you've got any questions!", fix: 'Please find the report attached. Please let me know if you have any questions.', level: 'B2', drill: 'Formalise: "Here\'s the file, hope it helps!"', answer: 'Please find the file attached. I hope it is useful.' },
];

